#!/usr/bin/env node
import { spawnSync } from "node:child_process"
import { mkdir, readFile, readdir, stat, writeFile } from "node:fs/promises"
import { builtinModules } from "node:module"
import { dirname, join } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"

// Keep this list byte-for-byte aligned with senpi loader.ts lines 145-165.
export const SENPI_LOADER_ALIASES = [
  "@earendil-works/pi-coding-agent",
  "@earendil-works/pi-agent-core",
  "@earendil-works/pi-tui",
  "@earendil-works/pi-ai",
  "@earendil-works/pi-ai/compat",
  "@earendil-works/pi-ai/oauth",
  "@code-yeongyu/senpi",
  "@mariozechner/pi-coding-agent",
  "@mariozechner/pi-agent-core",
  "@mariozechner/pi-tui",
  "@mariozechner/pi-ai",
  "@mariozechner/pi-ai/compat",
  "@mariozechner/pi-ai/oauth",
  "typebox",
  "typebox/compile",
  "typebox/value",
  "@sinclair/typebox",
  "@sinclair/typebox/compile",
  "@sinclair/typebox/value",
]

const scriptDir = dirname(fileURLToPath(import.meta.url))
const pluginRoot = dirname(scriptDir)
const packageRoot = dirname(pluginRoot)
const repoRoot = join(packageRoot, "..", "..")
const entryPath = join(packageRoot, "src", "extension", "index.ts")
const outputPath = join(pluginRoot, "extensions", "omo.js")
const sourceRoots = [join(packageRoot, "src", "extension"), join(packageRoot, "src", "components")]
const builtinModuleNames = builtinModules.filter((moduleName) => !moduleName.startsWith("_"))
const externalSpecifiers = [
  ...SENPI_LOADER_ALIASES,
  ...builtinModuleNames,
  ...builtinModuleNames.map((moduleName) => `node:${moduleName}`),
]

export async function buildExtension(options = {}) {
  const output = options.outputPath ?? outputPath
  await mkdir(dirname(output), { recursive: true })
  run("bun", [
    "build",
    entryPath,
    "--target",
    "node",
    "--format",
    "esm",
    "--outfile",
    output,
    "--minify",
    ...externalSpecifiers.flatMap((specifier) => ["--external", specifier]),
  ])
  await normalizeBuiltinImports(output)
}

export async function checkExtensionCurrent(options = {}) {
  const output = options.outputPath ?? outputPath
  let outputStats
  try {
    outputStats = await stat(output)
  } catch (error) {
    if (isErrno(error, "ENOENT")) {
      return { ok: false, reason: "missing-output", output }
    }
    throw error
  }

  const latestSource = await latestMtimeMs(sourceRoots)
  if (latestSource > outputStats.mtimeMs) {
    return { ok: false, reason: "stale-output", output, latestSource, outputMtime: outputStats.mtimeMs }
  }

  return { ok: true, output }
}

async function latestMtimeMs(paths) {
  let latest = 0
  for (const path of paths) {
    const pathStats = await stat(path)
    latest = Math.max(latest, pathStats.mtimeMs)
    if (!pathStats.isDirectory()) continue
    const entries = await readdir(path, { withFileTypes: true })
    for (const entry of entries) {
      latest = Math.max(latest, await latestMtimeMs([join(path, entry.name)]))
    }
  }
  return latest
}

function run(command, args) {
  const result = spawnSync(command, args, {
    cwd: repoRoot,
    shell: process.platform === "win32",
    stdio: "inherit",
  })
  if (result.error !== undefined) throw result.error
  if (result.status !== 0) process.exit(result.status ?? 1)
}

async function normalizeBuiltinImports(output) {
  const bundled = await readFile(output, "utf8")
  // Whitespace-tolerant so minified output (`from"path"`, `import"path"`) normalizes too, not just the
  // spaced non-minified shape.
  const normalized = bundled.replace(
    /(from\s*["']|import\s*\(\s*["']|import\s*["'])([^"']+)(["'])/g,
    (match, prefix, specifier, suffix) => {
      if (specifier.startsWith("node:")) return match
      if (!builtinModuleNames.includes(specifier)) return match
      return `${prefix}node:${specifier}${suffix}`
    },
  )
  if (normalized !== bundled) {
    await writeFile(output, normalized)
  }
}

function isErrno(error, code) {
  return error instanceof Error && "code" in error && error.code === code
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  if (process.argv.includes("--check")) {
    const result = await checkExtensionCurrent()
    if (!result.ok) {
      console.error(`omo-senpi extension build is not current: ${result.reason}`)
      console.error(`output=${result.output}`)
      process.exit(1)
    }
    console.log(`omo-senpi extension build is current: ${result.output}`)
  } else {
    await buildExtension()
    console.log(`Built omo-senpi extension: ${outputPath}`)
  }
}

#!/usr/bin/env node

import { readFileSync, writeFileSync } from "node:fs"
import { dirname, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const scriptDir = dirname(fileURLToPath(import.meta.url))
const packageRoot = resolve(scriptDir, "../..")
const repoRoot = resolve(packageRoot, "../..")
const sourcePath = resolve(repoRoot, "packages/omo-codex/plugin/components/ultrawork/directive.md")
const targetPath = resolve(packageRoot, "src/components/ultrawork/generated-directive.ts")

const forbiddenDirectiveTokens = [
  "create_goal",
  "complete_goal",
  "add_subgoal",
  "update_plan",
  "multi_agent",
  "spawn_agent",
]

const forbiddenPatterns = [
  ...forbiddenDirectiveTokens.map((token) => new RegExp(token, "i")),
  /browser:control-in-app-browser/i,
  /Codex Browser plugin/i,
  /Browser plugin/i,
]

function normalizeNewlines(value) {
  return value.replace(/\r\n/g, "\n").replace(/\r/g, "\n")
}

function splitBlocks(value) {
  return normalizeNewlines(value).split(/\n{2,}/)
}

export function transformDirective(rawDirective) {
  const keptBlocks = []
  for (const block of splitBlocks(rawDirective)) {
    if (forbiddenPatterns.some((pattern) => pattern.test(block))) {
      continue
    }
    keptBlocks.push(block.trim())
  }

  return `${keptBlocks.filter((block) => block.length > 0).join("\n\n").trim()}\n`
}

function renderGeneratedModule(directive) {
  return [
    "export const FORBIDDEN_DIRECTIVE_TOKENS = [",
    ...forbiddenDirectiveTokens.map((token) => `  ${JSON.stringify(token)},`),
    "] as const",
    "",
    `export const SENPI_ULTRAWORK_DIRECTIVE = ${JSON.stringify(directive)} as const`,
    "",
  ].join("\n")
}

function readExpectedModule() {
  return renderGeneratedModule(transformDirective(readFileSync(sourcePath, "utf8")))
}

function main(argv) {
  const expected = readExpectedModule()
  if (argv.includes("--check")) {
    const actual = readFileSync(targetPath, "utf8")
    if (actual !== expected) {
      console.error(`generated directive drifted: ${targetPath}`)
      process.exit(1)
    }
    console.log(`generated directive is current: ${targetPath}`)
    return
  }

  writeFileSync(targetPath, expected)
  console.log(`generated ${targetPath}`)
}

main(process.argv.slice(2))

#!/usr/bin/env node
import { cp, mkdir, readdir, readFile, rm, stat, writeFile } from "node:fs/promises"
import { dirname, extname, join } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"

const pluginRoot = dirname(dirname(fileURLToPath(import.meta.url)))
const repoRoot = dirname(dirname(pluginRoot))
const skillsRoot = join(pluginRoot, "skills")

const skillSources = [
  {
    name: "ultrawork",
    source: join(repoRoot, "omo-codex", "plugin", "components", "ultrawork", "skills", "ultrawork"),
  },
  {
    name: "ulw-loop",
    source: join(repoRoot, "omo-codex", "plugin", "components", "ulw-loop", "skills", "ulw-loop"),
  },
]

const textExtensions = new Set([".md", ".yaml", ".yml", ".json", ".txt"])
const sectionHeadingsToStrip = new Set([
  "Codex Harness Tool Compatibility",
  "Codex Tool Mapping",
  "Codex subagent reliability",
  "Subagent-dependent transition barrier",
])
const forbiddenGuidancePattern = /\b(?:multi_agent|spawn_agent)\b/i

function isTextFile(path) {
  return textExtensions.has(extname(path))
}

function rewriteEditionNaming(content) {
  return content
    .replace(/\bon Codex\b/g, "for omo-senpi")
    .replace(/\bIn Codex\b/g, "In omo-senpi")
    .replace(/\bCodex App\b/g, "omo-senpi")
    .replace(/\bCodex CLI\b/g, "omo-senpi")
    .replace(/\bCodex\b/g, "omo-senpi")
    .replace(/\bcodex\b/g, "omo-senpi")
    .replace(/\blazycodex\b/g, "omo-senpi")
    .replace(/\bLazyCodex\b/g, "omo-senpi")
}

function headingLevel(line) {
  const match = line.match(/^(#{1,6})\s+(.+?)\s*$/)
  return match === null ? undefined : match[1].length
}

function headingTitle(line) {
  const match = line.match(/^#{1,6}\s+(.+?)\s*$/)
  return match?.[1]?.replace(/`/g, "").trim()
}

function stripNamedSections(content) {
  const lines = content.split("\n")
  const kept = []
  let strippingLevel

  for (const line of lines) {
    const currentLevel = headingLevel(line)
    if (strippingLevel !== undefined && currentLevel !== undefined && currentLevel <= strippingLevel) {
      strippingLevel = undefined
    }

    if (strippingLevel !== undefined) {
      continue
    }

    const title = headingTitle(line)
    if (title !== undefined && sectionHeadingsToStrip.has(title)) {
      strippingLevel = currentLevel
      continue
    }

    kept.push(line)
  }

  return kept.join("\n")
}

function stripForbiddenGuidanceLines(content) {
  return content
    .split("\n")
    .filter((line) => !forbiddenGuidancePattern.test(line))
    .join("\n")
}

function normalizeBlankLines(content) {
  return content.replace(/\n{3,}/g, "\n\n")
}

function adaptSkillText(content) {
  return normalizeBlankLines(stripForbiddenGuidanceLines(stripNamedSections(rewriteEditionNaming(content))))
}

async function listFiles(root) {
  const entries = await readdir(root, { withFileTypes: true })
  const files = []

  for (const entry of entries) {
    const entryPath = join(root, entry.name)
    if (entry.isDirectory()) {
      files.push(...await listFiles(entryPath))
    } else if (entry.isFile()) {
      files.push(entryPath)
    }
  }

  return files
}

async function adaptSkillTree(skillRoot) {
  const files = await listFiles(skillRoot)
  for (const file of files) {
    if (!isTextFile(file)) continue

    const before = await readFile(file, "utf8")
    const after = adaptSkillText(before)
    if (after !== before) {
      await writeFile(file, after, "utf8")
    }
  }
}

async function assertSourceExists(source) {
  const sourceStat = await stat(source)
  if (!sourceStat.isDirectory()) {
    throw new Error(`${source} is not a directory`)
  }
}

export async function syncSkills() {
  await rm(skillsRoot, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 })
  await mkdir(skillsRoot, { recursive: true })

  for (const { name, source } of skillSources) {
    await assertSourceExists(source)
    const destination = join(skillsRoot, name)
    await cp(source, destination, { recursive: true })
    await adaptSkillTree(destination)
  }

  console.log(`synced ${skillSources.length} omo-senpi skills to ${skillsRoot}`)
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await syncSkills()
}

#!/usr/bin/env node
import { readFile, writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"

const scriptDir = dirname(fileURLToPath(import.meta.url))
const pluginRoot = dirname(scriptDir)
const packageRoot = dirname(pluginRoot)
const adapterManifestPath = join(packageRoot, "package.json")
const pluginManifestPath = join(pluginRoot, "package.json")

async function readJson(path) {
  return JSON.parse(await readFile(path, "utf8"))
}

async function writeJson(path, value) {
  await writeFile(path, `${JSON.stringify(value, null, 2)}\n`)
}

export async function syncVersion(options = {}) {
  const adapterManifest = await readJson(options.adapterManifestPath ?? adapterManifestPath)
  const pluginManifest = await readJson(options.pluginManifestPath ?? pluginManifestPath)
  const version = adapterManifest.version
  if (typeof version !== "string" || version.length === 0) {
    throw new Error("Cannot sync omo-senpi plugin version: adapter package.json has no version")
  }

  const changed = pluginManifest.version !== version
  if (changed && options.check === true) {
    return { ok: false, version, current: pluginManifest.version }
  }
  if (changed) {
    pluginManifest.version = version
    await writeJson(options.pluginManifestPath ?? pluginManifestPath, pluginManifest)
  }
  return { ok: true, version, changed }
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const result = await syncVersion({ check: process.argv.includes("--check") })
  if (!result.ok) {
    console.error(`omo-senpi plugin/package.json version mismatch: expected ${result.version}, found ${result.current}`)
    process.exit(1)
  }
  console.log(`omo-senpi plugin/package.json version ${result.version}${result.changed ? " synced" : " current"}`)
}
